const crypto = require('crypto');
const item = $input.first();
const payload = item.json ?? {};
const body = payload.body ?? {};
const headers = payload.headers ?? {};
const rawBodyBase64 = item.binary?.data?.data;
const signature = String(headers['x-cashflow-signature-sha256'] ?? headers['X-Cashflow-Signature-Sha256'] ?? '');
const secret = $env.N8N_CHATBOT_WEBHOOK_SECRET;

if (!secret || !/^[a-f0-9]{64}$/i.test(signature)) {
  throw new Error('Unauthorized webhook request');
}

const rawBody = typeof rawBodyBase64 === 'string'
  ? Buffer.from(rawBodyBase64, 'base64')
  : Buffer.from(JSON.stringify(body));
const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const receivedBuffer = Buffer.from(signature, 'hex');
const expectedBuffer = Buffer.from(expected, 'hex');

if (receivedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(receivedBuffer, expectedBuffer)) {
  throw new Error('Unauthorized webhook request');
}

return [{ json: body }];

const http = require('http');
const https = require('https');
const { URL } = require('url');

const body = $input.first().json;
const locale = ['vi', 'en', 'ja'].includes(body.locale) ? body.locale : 'vi';
const question = String(body.question ?? '').trim();
const endpoint = $env.N8N_AI_CHAT_COMPLETIONS_URL;
const apiKey = $env.N8N_AI_API_KEY;
const model = $env.N8N_AI_MODEL;

if (!question) {
  throw new Error('CashFlow question is required');
}

if (!endpoint || !apiKey || !model) {
  throw new Error('AI provider is not configured');
}

const languageNames = { vi: 'Vietnamese', en: 'English', ja: 'Japanese' };
const systemPrompt = [
  'You are CashFlow Manager financial coach for an offline-first personal finance app.',
  `Write in ${languageNames[locale]}.`,
  'You only know the user question and locale provided in this request. Do not claim access to bank accounts, transactions, wallets, files, external services, or hidden app data.',
  'Give practical budgeting, cashflow, savings, and expense-tracking guidance. Keep it conservative, educational, and non-judgmental.',
  'Do not provide legal, tax, lending, insurance, securities, crypto, or guaranteed investment advice. Suggest consulting a qualified professional for high-stakes decisions.',
  'If the question asks for unavailable personal data analysis, explain the limitation and suggest what information the user can review inside CashFlow Manager.',
  'Return JSON only. The JSON object must have answer:string and suggestions:string[]. answer should be 2-4 concise sentences. suggestions should contain 3-5 short actionable next steps.'
].join(' ');

const payload = {
  model,
  temperature: 0.2,
  response_format: { type: 'json_object' },
  messages: [
    {
      role: 'system',
      content: systemPrompt
    },
    {
      role: 'user',
      content: JSON.stringify({ question, locale })
    }
  ]
};

const requestJson = JSON.stringify(payload);
const url = new URL(endpoint);
const client = url.protocol === 'https:' ? https : http;
const data = await new Promise((resolve, reject) => {
  const request = client.request(url, {
    method: 'POST',
    headers: {
      authorization: `Bearer ${apiKey}`,
      'content-type': 'application/json',
      'content-length': Buffer.byteLength(requestJson)
    },
    timeout: 10000
  }, (response) => {
    let responseBody = '';
    response.setEncoding('utf8');
    response.on('data', (chunk) => { responseBody += chunk; });
    response.on('end', () => {
      if (response.statusCode < 200 || response.statusCode >= 300) {
        reject(new Error('AI provider request failed'));
        return;
      }
      try {
        resolve(JSON.parse(responseBody));
      } catch {
        reject(new Error('AI provider returned invalid JSON'));
      }
    });
  });
  request.on('timeout', () => request.destroy(new Error('AI provider request timed out')));
  request.on('error', reject);
  request.write(requestJson);
  request.end();
});

const content = data?.choices?.[0]?.message?.content;
let parsed;
try {
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch {
  throw new Error('AI provider returned non-JSON content');
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  throw new Error('AI provider returned an invalid response');
}

const answer = typeof parsed.answer === 'string' ? parsed.answer.trim() : '';
const rawSuggestions = parsed.suggestions;

if (!Array.isArray(rawSuggestions)) {
  throw new Error('AI provider returned an invalid response');
}

const suggestions = rawSuggestions.map((item) => (typeof item === 'string' ? item.trim() : ''));

if (!answer || suggestions.length < 3 || suggestions.length > 5 || suggestions.some((item) => !item)) {
  throw new Error('AI provider returned an invalid response');
}

return [{ json: { answer, suggestions } }];
